INSERT INTO `social_media_platforms` (`id`, `name`, `icon`, `description`, `status`, `created_at`, `updated_at`) VALUES
(1, 'Facebook', NULL, 'A social networking site that allows users to connect with friends, share updates, photos, and videos.', 1, '2024-08-17 12:39:21', '2024-08-17 12:39:21'),
(2, 'Instagram', NULL, 'A photo and video-sharing platform, known for its focus on visual content and Stories.', 1, '2024-08-17 12:39:21', '2024-08-17 12:39:21'),
(3, 'Twitter', NULL, 'A microblogging platform where users post short updates, known as tweets.', 1, '2024-08-17 12:46:03', '2024-08-17 12:46:03'),
(4, 'LinkedIn', NULL, 'A professional networking platform focused on career development and business connections.', 1, '2024-08-17 12:46:03', '2024-08-17 12:46:03'),
(5, 'TikTok', NULL, 'A video-sharing platform popular for its short-form videos, often featuring music, dance, and trends.', 1, '2024-08-17 12:46:03', '2024-08-17 12:46:03'),
(6, 'Snapchat', NULL, 'A multimedia messaging app known for its disappearing messages and stories.', 1, '2024-08-17 12:46:03', '2024-08-17 12:46:03'),
(7, 'Pinterest', NULL, 'A platform where users can discover and save ideas, mostly through images, related to various topics like fashion, home decor, and recipes.', 1, '2024-08-17 12:46:03', '2024-08-17 12:46:03'),
(8, 'Reddit', NULL, 'A community-based platform where users can discuss a wide range of topics through posts and comments.', 1, '2024-08-17 12:46:03', '2024-08-17 12:46:03'),
(9, 'YouTube', NULL, 'A video-sharing platform where users can upload, watch, and comment on videos across various categories.', 1, '2024-08-17 12:46:03', '2024-08-17 12:46:03'),
(10, 'WhatsApp', NULL, 'A messaging app that also supports voice and video calls, widely used for communication.', 1, '2024-08-17 12:46:03', '2024-08-17 12:46:03'),
(11, 'Telegram', NULL, 'A messaging app known for its focus on privacy and security, with features like channels and bots.', 1, '2024-08-17 12:46:03', '2024-08-17 12:46:03'),
(12, 'Tumblr', NULL, 'A microblogging and social networking platform known for its eclectic mix of content and creative communities.', 1, '2024-08-17 12:46:03', '2024-08-17 12:46:03'),
(13, 'Discord', NULL, 'Originally a platform for gamers, now used more broadly for community building through text, voice, and video chat.', 1, '2024-08-17 12:46:03', '2024-08-17 12:46:03'),
(14, 'Clubhouse', NULL, 'An audio-based social networking app where users can join rooms to listen to or participate in discussions.', 1, '2024-08-17 12:46:03', '2024-08-17 12:46:03'),
(15, 'WeChat', NULL, 'A Chinese multi-purpose messaging, social media, and mobile payment app.', 1, '2024-08-17 12:46:03', '2024-08-17 12:46:03'),
(16, 'Quora', NULL, 'A question-and-answer platform where users can ask questions, share knowledge, and discuss various topics.', 1, '2024-08-17 12:46:03', '2024-08-17 12:46:03'),
(17, 'Viber', NULL, 'A messaging app that supports text, voice, and video communication, along with public chat groups.', 1, '2024-08-17 12:46:03', '2024-08-17 12:46:03'),
(18, 'Signal', NULL, 'A privacy-focused messaging app known for its end-to-end encryption.', 1, '2024-08-17 12:46:03', '2024-08-17 12:46:03'),
(19, 'Medium', NULL, 'A blogging platform where users can write and share articles, often used by thought leaders and professionals.', 1, '2024-08-17 12:46:03', '2024-08-17 12:46:03'),
(20, 'Flickr', NULL, 'A photo-sharing platform popular among photographers for storing and showcasing images.', 1, '2024-08-17 12:46:03', '2024-08-17 12:46:03'),
(21, 'Twitch', NULL, 'A live-streaming platform primarily focused on gaming, but also hosts streams on other topics like music and creative arts.', 1, '2024-08-17 12:46:03', '2024-08-17 12:46:03'),
(22, 'Mix (formerly StumbleUpon)', NULL, 'A content discovery platform where users can find and curate articles, videos, and images based on their interests.', 1, '2024-08-17 12:46:03', '2024-08-17 12:46:03'),
(23, 'Mastodon', NULL, 'A decentralized social network that functions similarly to Twitter, with users joining specific communities or \"instances.\"', 1, '2024-08-17 12:46:03', '2024-08-17 12:46:03'),
(24, 'Gab', NULL, 'A social network known for its focus on free speech, often attracting users who have been banned from other platforms.', 1, '2024-08-17 12:46:03', '2024-08-17 12:46:03'),
(25, 'Parler', NULL, 'A microblogging and social networking service, known for its user base that includes a large number of conservatives.', 1, '2024-08-17 12:46:03', '2024-08-17 12:46:03'),
(26, 'VK (VKontakte)', NULL, 'A Russian-based social networking platform similar to Facebook, widely used in Russia and neighboring countries.', 1, '2024-08-17 12:46:03', '2024-08-17 12:46:03'),
(27, 'Line', NULL, 'A Japanese messaging app that also offers social networking features like a timeline and news feed.', 1, '2024-08-17 12:46:03', '2024-08-17 12:46:03'),
(28, 'MeWe', NULL, 'A social network focused on privacy, with no ads or tracking, offering a mix of Facebook-like features.', 1, '2024-08-17 12:46:03', '2024-08-17 12:46:03'),
(29, 'Weibo', NULL, 'A Chinese microblogging platform similar to Twitter, very popular in China.', 1, '2024-08-17 12:46:03', '2024-08-17 12:46:03'),
(30, 'Rumble', NULL, 'A video-sharing platform that has become popular as an alternative to YouTube, especially among content creators concerned with censorship.', 1, '2024-08-17 12:46:03', '2024-08-17 12:46:03'),
(31, 'Hive Social', NULL, 'A relatively new social media platform that combines features of Instagram and Twitter.', 1, '2024-08-17 12:46:03', '2024-08-17 12:46:03'),
(32, 'BeReal', NULL, 'A social app encouraging users to post one unfiltered photo per day, aiming for more authentic sharing.', 1, '2024-08-17 12:46:03', '2024-08-17 12:46:03'),
(33, 'Ello', NULL, 'Originally created as a \"Facebook alternative,\" this platform is now focused on the creative community, particularly artists and designers.', 1, '2024-08-17 12:46:03', '2024-08-17 12:46:03'),
(34, 'Diaspora', NULL, 'A decentralized social network where users control their data and connect with others through \"pods.\"', 1, '2024-08-17 12:46:03', '2024-08-17 12:46:03'),
(35, 'Caffeine', NULL, 'A live streaming platform focusing on broadcasting live sports, gaming, and entertainment content.', 1, '2024-08-17 12:46:03', '2024-08-17 12:46:03'),
(36, 'Triller', NULL, 'A social media app focused on music video creation and sharing, often compared to TikTok.', 1, '2024-08-17 12:46:03', '2024-08-17 12:46:03'),
(37, 'Nextdoor', NULL, 'A social networking service for neighborhoods, allowing users to connect with people in their local community.', 1, '2024-08-17 12:46:03', '2024-08-17 12:46:03'),
(38, 'Steemit', NULL, 'A blockchain-based social media platform where users earn cryptocurrency for posting and curating content.', 1, '2024-08-17 12:46:03', '2024-08-17 12:46:03'),
(39, 'Bumble', NULL, 'Known primarily as a dating app, it also has features for networking (Bumble Bizz) and finding friends (Bumble BFF).', 1, '2024-08-17 12:46:03', '2024-08-17 12:46:03'),
(40, 'Patreon', NULL, 'While not a traditional social network, it allows creators to build and maintain communities through paid memberships, offering exclusive content.', 1, '2024-08-17 12:46:03', '2024-08-17 12:46:03'),
(41, 'Clubhouse', NULL, 'An audio-based platform where users can join live discussions or host their own rooms on various topics.', 1, '2024-08-17 12:46:03', '2024-08-17 12:46:03');
